def linear(a, x):
    steps = 0
    for v in a:
        steps += 1
        if v == x:
            return steps
    return steps

def binary(a, x):
    lo, hi, steps = 0, len(a) - 1, 0
    while lo <= hi:
        steps += 1
        mid = (lo + hi) // 2
        if a[mid] == x:
            return steps
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return steps

data = list(range(1000))
print(linear(data, 999), binary(data, 999))   # 1000 vs ~10

